package com.quant.core.model.signal;

import com.quant.common.enums.SignalDirection;

import java.time.Instant;
import java.util.UUID;

/**
 * A trading signal generated by a strategy.
 */
public record Signal(
    String signalId,
    String symbol,
    SignalDirection direction,
    double strength,
    String strategyName,
    Instant timestamp,
    String reason
) {
    /**
     * Create a buy (long) signal.
     */
    public static Signal buy(String symbol, double strength, String strategyName, String reason) {
        return new Signal(UUID.randomUUID().toString().substring(0, 12),
            symbol, SignalDirection.LONG, strength, strategyName, Instant.now(), reason);
    }

    /**
     * Create a buy signal with default strength.
     */
    public static Signal buy(String symbol, double strength) {
        return buy(symbol, strength, "unknown", "");
    }

    /**
     * Create a sell (close long) signal.
     */
    public static Signal sell(String symbol, String strategyName, String reason) {
        return new Signal(UUID.randomUUID().toString().substring(0, 12),
            symbol, SignalDirection.FLAT, 1.0, strategyName, Instant.now(), reason);
    }

    /**
     * Create a sell signal with default params.
     */
    public static Signal sell(String symbol) {
        return sell(symbol, "unknown", "");
    }

    /**
     * Create a short signal.
     */
    public static Signal shortSell(String symbol, double strength, String strategyName, String reason) {
        return new Signal(UUID.randomUUID().toString().substring(0, 12),
            symbol, SignalDirection.SHORT, strength, strategyName, Instant.now(), reason);
    }

    /**
     * Whether this signal suggests a long position.
     */
    public boolean isLong() {
        return direction == SignalDirection.LONG;
    }

    /**
     * Whether this signal suggests exiting.
     */
    public boolean isExit() {
        return direction == SignalDirection.FLAT;
    }

    /**
     * Whether this signal suggests a short position.
     */
    public boolean isShort() {
        return direction == SignalDirection.SHORT;
    }
}
